import type { CartLine } from '#shared/types/cart'

export interface Quote {
  subtotal: string
  discount: string
  total: string
}

export interface PricedCents {
  subtotal: number
  discount: number
  total: number
}

/** Authoritative amounts in cents for a set of lines and an optional discount code. */
export function priceLines(lines: CartLine[], code?: string): PricedCents {
  const subtotal = sumBy(lines, line => (findProduct(line.slug)?.priceCents ?? 0) * line.qty)
  const discount = computeDiscount(subtotal, discountPercent(code))
  return { subtotal, discount, total: subtotal - discount }
}

export function computeQuote(lines: CartLine[], code?: string): Quote {
  const { subtotal, discount, total } = priceLines(lines, code)
  return {
    subtotal: formatMoney(subtotal),
    discount: formatMoney(discount),
    total: formatMoney(total),
  }
}

import type { CartLine } from './cart'

/** Response of `POST /api/orders`, amounts formatted like the quote API (`19.99 USD`). */
export interface OrderSummary {
  id: string
  subtotal: string
  discount: string
  total: string
}

/** A line as stored on the order, with the product name captured at order time. */
export interface OrderLine extends CartLine {
  name: string
}

/** Response of `GET /api/orders/:id`. */
export interface Order extends OrderSummary {
  lines: OrderLine[]
}

import type { CartLine } from '#shared/types/cart'
import type { Order, OrderLine, OrderSummary } from '#shared/types/order'

/** Orders kept in server memory, keyed by id. Lost on restart. */
const orders = new Map<string, Order>()

/** Validates the body and returns the lines, throwing 400 on bad input. */
export function parseOrderLines(lines: unknown): CartLine[] {
  if (!Array.isArray(lines) || lines.length === 0) {
    throw createError({ statusCode: 400, statusMessage: 'lines must be a non-empty array' })
  }
  return lines.map((line) => {
    const slug = (line as CartLine | null)?.slug
    const qty = (line as CartLine | null)?.qty
    if (typeof slug !== 'string' || !findProduct(slug)) {
      throw createError({ statusCode: 400, statusMessage: `unknown product: ${String(slug)}` })
    }
    if (!Number.isInteger(qty) || (qty as number) < 1) {
      throw createError({ statusCode: 400, statusMessage: `invalid qty for ${slug}` })
    }
    return { slug, qty: qty as number }
  })
}

/** Stores an order with amounts charged by the server. */
export function createOrder(lines: CartLine[], code?: string): OrderSummary {
  const priced = priceLines(lines, code)
  const order: Order = {
    id: crypto.randomUUID(),
    subtotal: formatMoney(priced.subtotal),
    discount: formatMoney(priced.discount),
    total: formatMoney(priced.total),
    lines: lines.map<OrderLine>(line => ({ slug: line.slug, qty: line.qty, name: findProduct(line.slug)!.name })),
  }
  orders.set(order.id, order)
  return summaryOf(order)
}

export function getOrder(id: string): Order | undefined {
  return orders.get(id)
}

export function summaryOf(order: OrderSummary): OrderSummary {
  return { id: order.id, subtotal: order.subtotal, discount: order.discount, total: order.total }
}

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: unknown, code?: string }>(event)
  return createOrder(parseOrderLines(body?.lines), body?.code)
})

export default defineEventHandler((event) => {
  const id = getRouterParam(event, 'id') ?? ''
  const order = getOrder(id)
  if (!order) {
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  }
  return order
})

